Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "One card per lab in a row of four: name, lead, composite score, band pill, teams by band, and a six-quarter composite sparkline.",
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "background": "transparent",
  "params": [
    {
      "name": "evergreen",
      "expr": "pbiColor(0)"
    },
    {
      "name": "emerald",
      "expr": "pbiColor(1)"
    },
    {
      "name": "sage",
      "value": "#DCE8E0"
    },
    {
      "name": "amber",
      "expr": "pbiColor(3)"
    },
    {
      "name": "red",
      "expr": "pbiColor(4)"
    },
    {
      "name": "ink",
      "expr": "pbiColor(0)"
    },
    {
      "name": "muted",
      "expr": "pbiColor(6)"
    },
    {
      "name": "line",
      "expr": "pbiColor(8)"
    },
    {
      "name": "surface",
      "value": "#FFFFFF"
    },
    {
      "name": "cream",
      "value": "#F7F6F2"
    },
    {
      "name": "goodFill",
      "value": "#DDF0E8"
    },
    {
      "name": "warnFill",
      "value": "#F5EAD6"
    },
    {
      "name": "badFill",
      "value": "#F3E0DA"
    },
    {
      "name": "labOrder",
      "value": [
        "core",
        "customer",
        "payments",
        "data"
      ]
    },
    {
      "name": "cardGap",
      "value": 16
    },
    {
      "name": "cardW",
      "expr": "max(1, (width - 3 * cardGap) / 4)"
    },
    {
      "name": "scoreY",
      "expr": "max(80, height - 50)"
    }
  ],
  "transform": [
    {
      "calculate": "isValid(datum.labOrder) && datum.labOrder !== '''' ? toNumber(datum.labOrder) : indexof(labOrder, datum[''LabKey'']) < 0 ? length(labOrder) : indexof(labOrder, datum[''LabKey''])",
      "as": "labRank"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "card"
        }
      ],
      "sort": [
        {
          "field": "labRank",
          "order": "ascending"
        },
        {
          "field": "LabName",
          "order": "ascending"
        }
      ]
    },
    {
      "calculate": "(datum.card - 1) * (cardW + cardGap)",
      "as": "cellX"
    },
    {
      "calculate": "datum.cellX + cardW",
      "as": "cellX2"
    },
    {
      "calculate": "lower(datum[''Band Key''] + '''')",
      "as": "bandId"
    },
    {
      "calculate": "isValid(datum[''LabCode'']) && datum[''LabCode''] !== '''' ? datum[''LabCode''] + '''' : upper(substring(datum[''LabName''] + '''', 0, 2))",
      "as": "chipCode"
    },
    {
      "calculate": "isValid(datum[''LabColour'']) && datum[''LabColour''] !== '''' ? datum[''LabColour''] + '''' : muted",
      "as": "chipColour"
    },
    {
      "calculate": "datum.cellX + 24",
      "as": "chipX"
    },
    {
      "calculate": "datum.cellX + 46",
      "as": "chipX2"
    },
    {
      "calculate": "datum.cellX + 35",
      "as": "chipMid"
    },
    {
      "calculate": "{''healthy'': ''HEALTHY'', ''watch'': ''WATCH'', ''act'': ''ACT''}[datum.bandId] || upper(datum.bandId)",
      "as": "bandWord"
    },
    {
      "calculate": "datum.bandId === ''healthy'' ? emerald : datum.bandId === ''watch'' ? amber : datum.bandId === ''act'' ? red : muted",
      "as": "bandKey"
    },
    {
      "calculate": "toNumber(datum[''Teams Healthy Display'']) + '' healthy · '' + toNumber(datum[''Teams Watch Display'']) + '' watch · '' + toNumber(datum[''Teams Needing Action Display'']) + '' act''",
      "as": "teamsText"
    },
    {
      "calculate": "[toNumber(datum[''Score Q1'']), toNumber(datum[''Score Q2'']), toNumber(datum[''Score Q3'']), toNumber(datum[''Score Q4'']), toNumber(datum[''Score Q5'']), toNumber(datum[''Composite''])]",
      "as": "quarterScores"
    },
    {
      "calculate": "extent(datum.quarterScores)[0]",
      "as": "cardMin"
    },
    {
      "calculate": "extent(datum.quarterScores)[1]",
      "as": "cardMax"
    },
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "cardMin",
          "as": "allMin"
        },
        {
          "op": "max",
          "field": "cardMax",
          "as": "allMax"
        }
      ]
    },
    {
      "calculate": "min(datum.allMin, 60) - 4",
      "as": "sparkLow"
    },
    {
      "calculate": "min(100, max(datum.allMax, 88) + 3)",
      "as": "sparkHigh"
    },
    {
      "calculate": "datum.cellX + cardW * 0.56",
      "as": "sparkX0"
    },
    {
      "calculate": "datum.cellX2 - 24",
      "as": "sparkX1"
    },
    {
      "calculate": "52",
      "as": "sparkTop"
    },
    {
      "calculate": "scoreY + 4",
      "as": "sparkBase"
    }
  ],
  "encoding": {
    "tooltip": [
      {
        "field": "LabName",
        "title": "Lab"
      },
      {
        "field": "Lead",
        "title": "Lead"
      },
      {
        "field": "Composite",
        "title": "Composite"
      },
      {
        "field": "bandWord",
        "title": "Band"
      },
      {
        "field": "teamsText",
        "title": "Teams"
      }
    ],
    "opacity": {
      "condition": {
        "test": "datum.__selected__ === ''off''",
        "value": 0.35
      },
      "value": 1
    }
  },
  "layer": [
    {
      "params": [
        {
          "name": "__select__",
          "select": {
            "type": "point",
            "fields": [
              "LabKey"
            ],
            "on": "click",
            "clear": "dblclick"
          }
        }
      ],
      "mark": {
        "type": "rect",
        "y": 1,
        "y2": {
          "expr": "height - 1"
        },
        "cornerRadius": 18,
        "fill": {
          "expr": "surface"
        },
        "stroke": {
          "expr": "line"
        },
        "strokeWidth": 1
      },
      "encoding": {
        "x": {
          "field": "cellX",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "cellX2"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "y": 20,
        "dx": 54,
        "font": "Fraunces, Cambria, Georgia, serif",
        "fontSize": 19,
        "fontWeight": 600,
        "color": {
          "expr": "ink"
        },
        "limit": {
          "expr": "max(40, cardW - 78)"
        }
      },
      "encoding": {
        "x": {
          "field": "cellX",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "LabName"
        }
      }
    },
    {
      "mark": {
        "type": "rect",
        "y": 22,
        "y2": 40,
        "cornerRadius": 4
      },
      "encoding": {
        "x": {
          "field": "chipX",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "chipX2"
        },
        "color": {
          "field": "chipColour",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "y": 31,
        "align": "center",
        "baseline": "middle",
        "font": "JetBrains Mono, Consolas, monospace",
        "fontSize": 10,
        "fontWeight": 700,
        "color": {
          "expr": "surface"
        }
      },
      "encoding": {
        "x": {
          "field": "chipMid",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "chipCode"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "y": 46,
        "dx": 24,
        "fontSize": 13,
        "color": {
          "expr": "muted"
        },
        "limit": {
          "expr": "max(40, cardW * 0.56 - 32)"
        }
      },
      "encoding": {
        "x": {
          "field": "cellX",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "Lead"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "y": {
          "expr": "scoreY"
        },
        "dx": 24,
        "font": "Fraunces, Cambria, Georgia, serif",
        "fontSize": 34,
        "fontWeight": 600,
        "color": {
          "expr": "ink"
        }
      },
      "encoding": {
        "x": {
          "field": "cellX",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "Composite"
        }
      }
    },
    {
      "transform": [
        {
          "calculate": "34 + length(datum.bandWord) * 7.4",
          "as": "pillW"
        },
        {
          "calculate": "datum.cellX + 92",
          "as": "pillX"
        },
        {
          "calculate": "datum.pillX + datum.pillW",
          "as": "pillX2"
        },
        {
          "calculate": "scoreY - 12",
          "as": "pillMid"
        },
        {
          "calculate": "datum.pillMid - 12",
          "as": "pillY"
        },
        {
          "calculate": "datum.pillMid + 12",
          "as": "pillY2"
        },
        {
          "calculate": "datum.pillX + 15",
          "as": "pillDotX"
        },
        {
          "calculate": "datum.pillX + 25",
          "as": "pillTextX"
        },
        {
          "calculate": "datum.bandId === ''healthy'' ? goodFill : datum.bandId === ''watch'' ? warnFill : datum.bandId === ''act'' ? badFill : sage",
          "as": "pillFill"
        }
      ],
      "layer": [
        {
          "mark": {
            "type": "rect",
            "cornerRadius": 12,
            "strokeWidth": 1,
            "strokeOpacity": 0.35
          },
          "encoding": {
            "x": {
              "field": "pillX",
              "type": "quantitative",
              "scale": null
            },
            "x2": {
              "field": "pillX2"
            },
            "y": {
              "field": "pillY",
              "type": "quantitative",
              "scale": null
            },
            "y2": {
              "field": "pillY2"
            },
            "fill": {
              "field": "pillFill",
              "type": "nominal",
              "scale": null
            },
            "stroke": {
              "field": "bandKey",
              "type": "nominal",
              "scale": null
            }
          }
        },
        {
          "mark": {
            "type": "circle",
            "size": 64
          },
          "encoding": {
            "x": {
              "field": "pillDotX",
              "type": "quantitative",
              "scale": null
            },
            "y": {
              "field": "pillMid",
              "type": "quantitative",
              "scale": null
            },
            "color": {
              "field": "bandKey",
              "type": "nominal",
              "scale": null
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "middle",
            "font": "JetBrains Mono, Consolas, monospace",
            "fontSize": 12.5,
            "fontWeight": 600,
            "color": {
              "expr": "ink"
            }
          },
          "encoding": {
            "x": {
              "field": "pillTextX",
              "type": "quantitative",
              "scale": null
            },
            "y": {
              "field": "pillMid",
              "type": "quantitative",
              "scale": null
            },
            "text": {
              "field": "bandWord"
            }
          }
        }
      ]
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "y": {
          "expr": "scoreY + 26"
        },
        "dx": 24,
        "fontSize": 12.5,
        "color": {
          "expr": "muted"
        },
        "limit": {
          "expr": "max(40, cardW - 48)"
        }
      },
      "encoding": {
        "x": {
          "field": "cellX",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "teamsText"
        }
      }
    },
    {
      "transform": [
        {
          "calculate": "sequence(0, 6)",
          "as": "quarterIndex"
        },
        {
          "flatten": [
            "quarterScores",
            "quarterIndex"
          ],
          "as": [
            "quarterScore",
            "qi"
          ]
        },
        {
          "calculate": "datum.sparkX0 + (datum.sparkX1 - datum.sparkX0) * datum.qi / 5",
          "as": "sx"
        },
        {
          "calculate": "datum.sparkBase - (datum.sparkBase - datum.sparkTop) * (clamp(datum.quarterScore, datum.sparkLow, datum.sparkHigh) - datum.sparkLow) / (datum.sparkHigh - datum.sparkLow)",
          "as": "sy"
        }
      ],
      "layer": [
        {
          "mark": {
            "type": "area",
            "color": {
              "expr": "emerald"
            },
            "fillOpacity": 0.15
          },
          "encoding": {
            "x": {
              "field": "sx",
              "type": "quantitative",
              "scale": null
            },
            "y": {
              "field": "sy",
              "type": "quantitative",
              "scale": null
            },
            "y2": {
              "field": "sparkBase"
            },
            "detail": {
              "field": "LabKey"
            }
          }
        },
        {
          "mark": {
            "type": "line",
            "strokeWidth": 1.75,
            "color": {
              "expr": "evergreen"
            }
          },
          "encoding": {
            "x": {
              "field": "sx",
              "type": "quantitative",
              "scale": null
            },
            "y": {
              "field": "sy",
              "type": "quantitative",
              "scale": null
            },
            "detail": {
              "field": "LabKey"
            },
            "order": {
              "field": "qi",
              "type": "quantitative"
            }
          }
        },
        {
          "transform": [
            {
              "filter": "datum.qi === 5"
            }
          ],
          "mark": {
            "type": "circle",
            "size": 44,
            "stroke": {
              "expr": "surface"
            },
            "strokeWidth": 1.5
          },
          "encoding": {
            "x": {
              "field": "sx",
              "type": "quantitative",
              "scale": null
            },
            "y": {
              "field": "sy",
              "type": "quantitative",
              "scale": null
            },
            "color": {
              "field": "bandKey",
              "type": "nominal",
              "scale": null
            }
          }
        }
      ]
    }
  ]
}'

'{
  "background": "transparent",
  "font": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
  "padding": 8,
  "view": {
    "stroke": null
  },
  "title": {
    "font": "Fraunces, Cambria, Georgia, serif",
    "fontSize": 17,
    "fontWeight": 600,
    "color": "#0F4D43",
    "anchor": "start",
    "offset": 12
  },
  "axis": {
    "domain": false,
    "ticks": false,
    "grid": true,
    "gridColor": "#E6E8E2",
    "gridWidth": 1,
    "labelColor": "#5F6E69",
    "labelFont": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "labelFontSize": 12,
    "labelPadding": 8,
    "titleColor": "#5F6E69",
    "titleFont": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "titleFontSize": 12,
    "titleFontWeight": "normal"
  },
  "axisX": {
    "grid": false
  },
  "legend": {
    "disable": true
  },
  "range": {
    "category": [
      "#0F4D43",
      "#0B8A6B",
      "#5E8C82",
      "#B9852C",
      "#B6462F",
      "#2A6A5F",
      "#5F6E69",
      "#CFDDD4",
      "#D6D9D2"
    ]
  },
  "text": {
    "font": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "color": "#0F4D43"
  },
  "line": {
    "color": "#0F4D43",
    "strokeWidth": 2.5,
    "strokeJoin": "round",
    "strokeCap": "round"
  },
  "point": {
    "color": "#0B8A6B",
    "filled": true
  },
  "rule": {
    "color": "#D6D9D2"
  }
}'
